query:
SELECT COUNT(DISTINCT CONCAT(ROUND(latitude, 4), ',', ROUND(longitude, 4))) as distinct_locations,
  COUNT(*) as total_geocoded
FROM pco_people WHERE status = 'active' AND latitude IS NOT NULL;

